# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_fend_a import D,DS,O,OS
FE=DS+[['中古英语 defens 缩短为 fence','防卫；起保护作用的东西'],['英语 fence','围栏；动词发展出围住、防卫、击剑等义']]
WB=[
E('defenceless','/dɪˈfensləs/','无力自卫的；没有防护的〔英式常用〕','保护被拿走后，面对威胁的一方只能暴露在那里。','defence + -less“没有”，与 defenseless 是拼写变体。',DS+[['英语 defence + -less → defenceless','没有防御能力的']],'英式文本中常用 defenceless 描写缺少保护的个体或群体。它强调具体处境：一个人平时很有能力，在突如其来的威胁前也可能被留在 defenceless 的状态。读写时注意与所选英美拼写保持一致。','leave someone defenceless；defenceless civilians；defenceless against an attack。','defenceless 是缺少防御能力；undefended 更直接说没有人防守。一个地方暂时 undefended，不一定永远无法防御。',('The villagers felt defenceless after the guards left.','守卫离开后，村民们觉得自己失去了保护。'),('The shelter protects defenceless animals.','这家收容所保护无力自卫的动物。'),sources=['https://en.wiktionary.org/wiki/defenceless','https://www.etymonline.com/word/defense']),
E('defensible','/dɪˈfensəbəl/','可以防守的；有理由支持或辩护的','面对攻击，你有办法挡住；面对质疑，你拿得出站得住的理由。','defens- 与 -ible“能够……的”相连；历史上经法语 defensable、拉丁 defensibilis 等形式借入。',D+[['拉丁 defensibilis／法语 defensable','可防卫的'],['英语 defensible','可以防守；也指观点或决定可以合理辩护']],'a defensible position 可以是容易守住的地点，也可以是有根据的立场。工作中说 a defensible decision，意思是能解释为什么这样决定，经得起合理质疑，不保证所有人最后都同意。','a defensible argument；a defensible decision；a defensible position。','defensible 说“能讲得通”；defensive 说“采取防卫姿态”。一个词评价理由，一个词描述应对方式。',('Given the evidence, her conclusion is defensible.','根据这些证据，她的结论有理由成立。'),('They chose a defensible position on the hill.','他们在山上选择了一个便于防守的位置。'),sources=['https://www.etymonline.com/word/defensible','https://en.wiktionary.org/wiki/defensible']),
E('indefensible','/ˌɪndɪˈfensəbəl/','无法辩护的；无法防守的','被追问理由时，找不到足以撑住这个行为或立场的根据。','in-“不” + defensible“可辩护、可防卫的”。',D+[['英语 defensible → in- + defensible','可辩护 → 无法合理辩护'],['英语 indefensible','行为或立场站不住脚；也可指阵地无法守住']],'日常评论里 indefensible 常带很强的否定：不是“我暂时不同意”，而是认为这个行为或说法找不到合理辩护。它也可以按较具体的意义描述无法防守的军事位置。','indefensible behavior；morally indefensible；an indefensible position。','unpopular 只是不得人心，仍可能有充分理由；indefensible 判断的是理由或正当性无法成立。',('Blaming the victim was indefensible.','责怪受害者是无法辩护的。'),('The exposed position became indefensible.','这个暴露的阵地变得无法守住。'),sources=['https://www.etymonline.com/word/indefensible','https://en.wiktionary.org/wiki/indefensible']),
E('offensively','/əˈfensɪvli/','冒犯地；令人不快地；在进攻方面','同一个词可以描述话语刺人，也可以描述球队怎样主动得分。','offensive + -ly，保留 offensive 的“冒犯”与“进攻”两条意义。',O+[['拉丁 offens- 词族 → 英语 offensive','冒犯的；进攻的'],['英语 offensive + -ly → offensively','以冒犯方式；在进攻方面']],'speak offensively 是以冒犯人的方式说话；play well offensively 是进攻表现好。看到体育语境，别先把它翻成“无礼地”：这里是在评价进攻端的表现。','behave offensively；speak offensively；perform well offensively。','offensively 与 defensively 在比赛中可以对照进攻、防守；说话语气里则分别可能是冒犯别人、急于保护自己。',('He spoke offensively about her background.','他谈到她的背景时说了冒犯的话。'),('The team struggled offensively but defended well.','球队进攻不顺，不过防守做得不错。'),sources=['https://en.wiktionary.org/wiki/offensively','https://www.merriam-webster.com/dictionary/offensively']),
E('inoffensive','英 /ˌɪnəˈfensɪv/；美 /ˌɪnəˈfensɪv/','不冒犯人的；无害的；温和而不惹眼的','不会刺到别人，但也可能平平淡淡、没留下很深的印象。','in-“不” + offensive“冒犯的、令人不快的”。',O+[['英语 offensive → in- + offensive','冒犯的 → 不会引起冒犯的'],['英语 inoffensive','温和、无害；有时暗含缺少个性或冲击力']],'an inoffensive remark 是没有冒犯意味的话。评价电影或音乐 inoffensive，有时只是说它不会惹人不快，并不等于精彩。语气可能温和肯定，也可能是在说“没毛病，但没什么劲”。','an inoffensive joke；an inoffensive manner；pleasant but inoffensive。','inoffensive 说不招人反感；harmless 更一般地说不造成伤害。称作品 inoffensive，也不一定是在热情称赞它。',('It was an inoffensive joke about the weather.','那只是一个关于天气、没有冒犯意味的笑话。'),('The music was pleasant but rather inoffensive.','音乐挺悦耳，不过有些平淡。'),sources=['https://en.wiktionary.org/wiki/inoffensive','https://www.merriam-webster.com/dictionary/inoffensive']),
E('fender','英 /ˈfendə/；美 /ˈfendər/','护舷；挡泥板、翼子板〔尤美〕；壁炉护栏','放一个东西在前面或旁边，替真正要保护的东西挡一下。','现代可以联系 fend + -er“用于抵挡的东西”；历史解释也常视为 defender 的缩短形式。',D+[['古法语及中古英语 defender 词族 → fender','起防护作用的物件'],['英语 fender','船边护垫；壁炉护栏；车轮附近的防护板']],'船靠码头时，船边的 fender 用来缓冲碰撞；车辆的 fender 通常是车轮周围的翼子板或挡泥结构。共同点是保护、挡开，但具体部件随场景变化。汽车的 fender 不能一概译成前后保险杠。','a boat fender；a damaged fender；a bicycle fender；a fireplace fender。','bumper 通常是车辆前后的保险杠；fender 多在车轮周围。英式说汽车相应部位时也常用 wing。',('A rope held the fender between the boat and the dock.','一根绳子把护舷固定在船与码头之间。'),('The bicycle’s rear fender kept mud off her coat.','自行车后挡泥板挡住了溅向她外套的泥。'),sources=['https://www.etymonline.com/word/fender','https://en.wiktionary.org/wiki/fender']),
E('fence','/fens/','围栏；用围栏围住；击剑；销赃者或销赃','防护先是一种作用，后来变成看得见、绕着地方立起来的东西。','由中古英语 defens“防御”缩短而来；与 defence 同源。',FE,'最常见的 fence 是围栏，动词 fence an area 就是围起来。历史上它还保留防卫、用剑攻防的意义，形成今天的击剑用法。犯罪报道中的 a fence 指销赃者，属于同一词后来的特殊用法；不要在普通花园场景里套进去。','a wooden fence；put up a fence；fence off an area；sit on the fence。','wall 通常是较实的墙；fence 是围栏。sit on the fence 借“坐在边界上”说暂不选边，不是要求真的坐上围栏。',('A wooden fence separates the two gardens.','一道木围栏隔开了两个花园。'),('They fenced off the damaged area.','他们把受损区域围了起来。'),('She is still on the fence about the proposal.','她对这个提议还没有拿定主意。'),sources=['https://www.etymonline.com/word/fence','https://en.wiktionary.org/wiki/fence']),
E('fencer','英 /ˈfensə/；美 /ˈfensər/','击剑者；击剑运动员；修建围栏的人','用剑攻防的人，名称仍连着“防卫”这条老词义。','fence + -er“做这件事的人”；fence 在这里常用其击剑动词义。',FE+[['英语 fence + -er → fencer','击剑的人；也可指建围栏的人']],'体育报道中的 fencer 通常就是击剑运动员，不是“守着围栏的人”。在建筑或农场语境，fencer 也能按另一项动词义指安装围栏的工人。具体看他说的是剑还是围栏工程。','an Olympic fencer；a skilled fencer；hire a fencer。','fencer 是人；fencing 可指运动或围栏材料。读同族词时，除了词根还要看后缀与语境。',('The young fencer won her first tournament.','这位年轻击剑选手赢得了她的第一场锦标赛。'),('They hired a fencer to replace the boundary fence.','他们雇了一名围栏工人更换边界围栏。'),sources=['https://en.wiktionary.org/wiki/fencer','https://www.merriam-webster.com/dictionary/fencer']),
E('fencing','/ˈfensɪŋ/','击剑；围栏材料；安装围栏','一条意义保留人的攻防动作，另一条变成隔开空间的材料与工作。','fence + -ing 可描述现代结构；早期英语也有从 defencing 缩短的形式，核心仍是防卫。',FE+[['英语 fencing；早期也与 defencing 的缩短相连','防卫行动'],['现代 fencing','击剑运动；围栏材料或围栏施工']],'take up fencing 是开始练击剑；buy fencing 多半是买围栏材料。材料义通常不可数，可以说 some fencing 或 meters of fencing；一段具体围栏则常说 a fence。先看动作与物品的区别，两个义就不难分。','take fencing lessons；wire fencing；install fencing；fencing equipment。','fencing equipment 在体育场多指击剑装备；fencing materials 在施工场景指围栏材料。单看 fencing 一个词不足以确定场景。',('He started fencing lessons at school.','他在学校开始上击剑课。'),('We need more wire fencing for the garden.','花园还需要更多铁丝围栏材料。'),sources=['https://www.etymonline.com/word/fencing','https://en.wiktionary.org/wiki/fencing']),
]
